"""Legacy query-oriented material preparation and historical review.

Current record-first entry: python -m curation.v4.record_flow.
This module remains for frozen query-pilot compatibility and shared execute().

No generation, knowledge extraction, canonical-data writes or implicit downloads.
Use the shared env Python. Run `python -m curation.v4.flow --help`.
"""
import argparse
from pathlib import Path
from demiflow.standalone import local_data
from .contracts import ROOT, SCHEMA, IdentityRegistry, code_fingerprint, digest, immutable, read, run_lock, source_code, runtime_version
from .sources import discover
from .operators import InspectSource, CollectRows, ScanSource, AssembleMaterial, SaveBundle


def execute(rows,*stages):
    ds=local_data().from_iter(lambda:iter(rows))
    for stage in stages:ds=ds.map_async(stage)
    return ds.run_stream(log_every=0)


def check_run_location(run,project,dataset):
    run=Path(run).resolve();project=Path(project).resolve();dataset=Path(dataset).resolve()
    if not run.is_relative_to(project/'state/curation') or run.is_relative_to(dataset):
        raise ValueError('run must be under project/state/curation, outside the dataset')


def inventory(dataset,project,run):
    check_run_location(run,project,dataset)
    with run_lock(run):
        sources=discover(dataset,project);collector=CollectRows()
        execute(sources,InspectSource(),collector)
        immutable(Path(run)/'code_snapshot.json',source_code())
        report={'schema':SCHEMA,'phase':'inventory','code_hash':code_fingerprint(),'runtime':runtime_version(),
                'sources':sorted(collector.results,key=lambda x:x['path']),
                'scope':'File presence and sampled schema only; not a full corpus count or evidence quality audit.'}
        immutable(Path(run)/'inventory.json',report)
    return report


def prepare(dataset,project,run,requests,max_rows,source_paths=None,blob_roots=(),max_images=8):
    if max_rows<1 or max_images<0:raise ValueError('positive row budget and nonnegative image budget required')
    if not requests:raise ValueError('explicit entry-validation requests required; this is not broad sampling')
    if len({(r.get('kind'),r.get('value')) for r in requests})!=len(requests):raise ValueError('duplicate request identity')
    for r in requests:
        if set(r)!={'kind','value'}:raise ValueError('request fields are kind and value; no implicit identity merge')
    dataset=Path(dataset).resolve();project=Path(project).resolve();run=Path(run).resolve()
    check_run_location(run,project,dataset)
    with run_lock(run):
        sources=discover(dataset,project)
        eligible={'legacy_concepts','qid_concepts','qid_concepts_base','legacy_docs','legacy_images','qid_images','wiki_pages','image_roles','gallery_captions','qid_graph'}
        sources=[s for s in sources if s['kind'] in eligible]
        if source_paths is not None:
            selected={str(Path(p).resolve()) for p in source_paths}
            unknown=selected-{s['path'] for s in sources}
            if unknown:raise ValueError(f'Unknown source paths: {sorted(unknown)}')
            sources=[s for s in sources if s['path'] in selected]
        if not sources:raise ValueError('no sources selected')
        code=code_fingerprint()
        manifest={'schema':SCHEMA,'phase':'entry_validation','dataset':str(dataset),'project':str(project),
                  'requests':requests,'sources':sources,'max_rows_per_source':max_rows,'max_images_per_concept':max_images,
                  'blob_roots':[str(Path(p).resolve()) for p in blob_roots],'code_hash':code,'runtime':runtime_version(),
                  'scope':'Explicit engineering cases, bounded scans; not V4 question sampling or a whole-concept completeness claim.',
                  'snapshot_note':'Source size/mtime/inode lock this run; selected records also retain hashes and original fields. No whole-file content-hash claim.'}
        immutable(run/'manifest.json',manifest)
        immutable(run/'code_snapshot.json',source_code())
        # Separate persistent identities from display names; no source-name merging.
        registry=IdentityRegistry(project/'state/curation/v4/identities.sqlite')
        try:ids=[registry.get(r) for r in requests]
        finally:registry.close()
        identity_kinds={'legacy_concepts','qid_concepts','qid_concepts_base'}
        first=CollectRows();first_op=ScanSource(run,requests,{},max_rows,code)
        if any(s['kind'] in identity_kinds for s in sources):execute([s for s in sources if s['kind'] in identity_kinds],first_op,first)
        links={}
        for scan in first.results:
            if scan['source']['kind'] not in ('qid_concepts','qid_concepts_base'):continue
            for match in scan['matches']:
                record=match['record'];qid=record['qid']
                for lang in ['en','zh']:
                    site=record.get(lang) or {}
                    if site.get('page_id') is not None:links.setdefault(qid,[]).append((lang,site['page_id']))
        links={k:sorted(set(v)) for k,v in links.items()}
        second=CollectRows();second_op=ScanSource(run,requests,links,max_rows,code)
        if any(s['kind'] not in identity_kinds for s in sources):execute([s for s in sources if s['kind'] not in identity_kinds],second_op,second)
        scans=sorted(first.results+second.results,key=lambda r:r['source']['path'])
        tasks=[{'request':r,'concept_id':cid,'task_id':digest({'manifest':manifest,'request':r,'concept_id':cid})} for r,cid in zip(requests,ids)]
        # Skip completed bundles before any byte verification or assembly work.
        done=[t for t in tasks if (run/'bundles'/f'{t["task_id"]}.json').exists()]
        pending=[t for t in tasks if t not in done]
        sink=SaveBundle(run)
        if pending:execute(pending,AssembleMaterial(scans,dataset,blob_roots,max_images),sink)
        bundles=[{'task_id':t['task_id'],'concept_id':t['concept_id'],'request':t['request'],
                  'path':str(run/'bundles'/f'{t["task_id"]}.json')} for t in tasks]
        report={'schema':SCHEMA,'phase':'materials_prepared','bundles':bundles,'sources':[{k:s[k] for k in ['source','status','scan']} for s in scans],
                'limitations':['No cross-source identity adjudication.','COS/network byte fetching not connected.','No knowledge extraction or evidence approval.','Bounded source scans do not prove absence.']}
        immutable(run/'report.json',report)
        return {**report,'execution':{'source_tasks_reused':first_op.reused+second_op.reused,'source_tasks_executed':first_op.executed+second_op.executed,'bundles_reused':len(done),'bundles_executed':len(pending)}}


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('action',choices=['inventory','prepare','review'])
    p.add_argument('--dataset',type=Path,default=ROOT/'datasets/demiwtg')
    p.add_argument('--project',type=Path,default=ROOT)
    p.add_argument('--run',type=Path,required=True)
    p.add_argument('--requests',type=Path,help='JSON list of explicit {kind: qid|legacy, value: ...} entry-validation requests')
    p.add_argument('--max-rows-per-source',type=int,default=500)
    p.add_argument('--max-images-per-concept',type=int,default=8)
    p.add_argument('--source',action='append',type=Path,help='Explicit source paths; omission scans all supported sources to the stated row budget')
    p.add_argument('--blob-root',action='append',type=Path,default=[],help='Additional local/mounted dataset roots containing blobs/...')
    a=p.parse_args()
    if a.action=='inventory':
        r=inventory(a.dataset,a.project,a.run);print('Inspected',len(r['sources']),'source entries; see',a.run/'inventory.json')
    elif a.action=='prepare':
        if not a.requests:p.error('prepare requires --requests')
        r=prepare(a.dataset,a.project,a.run,read(a.requests),a.max_rows_per_source,a.source,a.blob_root,a.max_images_per_concept)
        print(r['execution']);print('Material report:',a.run/'report.json')
    else:
        from .review import render
        print(render(a.run))

if __name__=='__main__':main()

code.knowledge_stages.py:
"""Individually cached stages for the small-batch knowledge-candidate pipeline."""
import asyncio
import base64
import io
import json
from pathlib import Path
from urllib.parse import urlsplit,urlunsplit,unquote
import httpx
from .contracts import digest,immutable,read
from .local_model import CallBudgetExceeded,UncertainPreviousCall
from .material_fetch import fetch_image
from . import knowledge_checks as check
from .quality_policy import material_disposition,quarantine_conflicts,image_followups,identity_followups,defer_invalid_identity_quotes
from .knowledge_prompts import SYSTEM,IDENTITY,EXTRACT,CONSOLIDATE,EVIDENCE


def material_id(m):return 'M'+digest({'kind':m['kind'],'record':m['record'],'provenance':m['provenance']})[:12]
def message(prompt,data):return [{'role':'system','content':SYSTEM},{'role':'user','content':prompt+'\n输入数据：\n'+json.dumps(data,ensure_ascii=False)}]

def text_of(m):
    if 'cleaning' in m:return m['cleaning']['text']
    r=m['record']
    if m['kind']=='legacy_docs':return m.get('document',{}).get('text','')
    if m['kind']=='wiki_pages':return '\n\n'.join((s.get('title','')+'\n'+s.get('text','')).strip() for s in r.get('sections',[]))
    return ''

def family(m):
    r=m['record'];url=r.get('url')
    if not url and m['kind']=='wiki_pages':url=f'https://{r.get("lang","en")}.wikipedia.org/wiki/{r.get("title","")}'
    if url:
        u=urlsplit(url);return urlunsplit((u.scheme,u.netloc.lower(),unquote(u.path).replace('_',' '),'',''))
    return m['material_id']

class Stage:
    concurrency=1;queue_depth=1;catch=()
    def __init__(self,run,config,model):self.run=Path(run);self.config=config;self.model=model;self.reused=0;self.executed=0
    async def __call__(self,row):
        path=self.run/'stages'/self.label/f'{row["case_id"]}.json'
        key=digest({'stage':self.label,'input':row,'config':self.config})
        if path.exists():
            saved=read(path)
            if saved['input_hash']!=key:raise ValueError('Stage inputs changed; use a new run')
            self.reused+=1;return saved['output']
        if row.get('blocked') and self.label!='export':out={**row,'skipped_stages':row.get('skipped_stages',[])+[self.label]}
        else:
            try:out=await self.process(row)
            except (ValueError,KeyError,TypeError,httpx.HTTPError,CallBudgetExceeded,UncertainPreviousCall) as e:
                out={**row,'blocked':{'stage':self.label,'reason':type(e).__name__,'detail':str(e)}}
        immutable(path,{'input_hash':key,'output':out});self.executed+=1;return out
    async def aclose(self):await self.model.aclose()

class CleanMaterials(Stage):
    label='clean'
    async def process(self,row):
        from .cleaning import clean_materials
        materials=await asyncio.to_thread(clean_materials,row['bundle'])
        return {**row,'cleaned_materials':materials,
                'cleaning_summary':[{'index':i,'kind':m['kind'],
                    'title':m['record'].get('title'),
                    'status':m['cleaning']['status'],'counts':m['cleaning']['counts'],
                    'warnings':m['cleaning']['warnings']} for i,m in enumerate(materials) if 'cleaning' in m]}

class ResolveIdentity(Stage):
    label='identity'
    async def process(self,row):
        bundle=row['bundle'];materials=[];identity=[];ineligible=[]
        for m in row['cleaned_materials']:
            if m['kind'] in ('legacy_concepts','qid_concepts','qid_concepts_base'):identity.append(m['record'])
            elif 'cleaning' in m and material_disposition(m['cleaning'])['status']=='pending':
                ineligible.append({'material_id':material_id(m),'reason':'pending_material_quality','disposition':material_disposition(m['cleaning']),
                                   'warnings':m.get('cleaning',{}).get('warnings',[])})
            elif text_of(m) or m['kind'] in ('legacy_images','qid_images'):
                materials.append({**m,'material_id':material_id(m)})
        docs=sorted([m for m in materials if text_of(m)],key=lambda m:m['material_id'])
        images=[m for m in materials if m['kind'] in ('legacy_images','qid_images')]
        # Spread the identity preview across page families before adding other versions.
        selected=[];seen=set()
        for m in docs:
            f=family(m)
            if f not in seen:selected.append(m);seen.add(f)
        images.sort(key=lambda m:(m.get('bytes',{}).get('status')!='verified_bytes',m['material_id']))
        selected=selected[:self.config['identity_docs']]+images[:self.config.get('identity_images',self.config['identity_docs'])]
        if not selected:return {**row,'identity_ineligible':ineligible,'blocked':{'stage':self.label,'reason':'no_materials_in_scanned_scope'},'identity':{'status':'insufficient'}}
        previews=[{'material_id':m['material_id'],'kind':m['kind'],'title':m['record'].get('title'),
                   'url':m['record'].get('url',m['record'].get('content_url')),
                   'caption':m['record'].get('caption'),'pixels_provided':False,'text_preview':text_of(m)[:500],
                   'text_spans':[{'start':a,'end':min(a+500,len(text_of(m))),'text':text_of(m)[a:a+500]}
                       for a in sorted({0,max(0,len(text_of(m))//2-250),max(0,len(text_of(m))-500)}) if text_of(m)]} for m in selected]
        result,call=await self.model.json(self.label,message(IDENTITY,{'request':bundle['request'],'source_identity_records':identity,'materials':previews}))
        result=defer_invalid_identity_quotes(result,previews)
        check.identity(result,selected,previews)
        out={**row,'identity_ineligible':ineligible,'identity':{**result,'reviewer':'local_model; not human identity adjudication','call':call},
             'identity_materials':selected,'identity_unexamined':[m['material_id'] for m in materials if m not in selected]}
        if result['status']!='resolved':out['blocked']={'stage':self.label,'reason':result['status'],'detail':result['reason']}
        return out

class OrganizeMaterials(Stage):
    label='organize'
    async def process(self,row):
        accepted=set(row['identity']['accepted_material_ids']);materials=[m for m in row['identity_materials'] if m['material_id'] in accepted]
        docs=[];images=[];duplicates=[];text_seen={};image_seen={};quality_deferred=[]
        for m in materials:
            if 'cleaning' in m and material_disposition(m['cleaning'])['status']=='pending':
                quality_deferred.append({'material_id':m['material_id'],'reason':'pending_material_quality','disposition':material_disposition(m['cleaning'])});continue
            text=text_of(m)
            if text:
                h=digest(' '.join(text.split()).encode())
                if h in text_seen:duplicates.append({'material_id':m['material_id'],'same_text_as':text_seen[h],'provenance':m['provenance']});continue
                text_seen[h]=m['material_id'];docs.append({**m,'text':text,'source_family':family(m)})
            elif m['kind'] in ('legacy_images','qid_images'):
                h=m['record'].get('sha256')
                if h in image_seen:duplicates.append({'material_id':m['material_id'],'same_bytes_as':image_seen[h],'provenance':m['provenance']});continue
                image_seen[h]=m['material_id'];images.append(m)
        docs=sorted(docs,key=lambda m:m['material_id'])
        selected=[];seen=set()
        for m in docs:
            if m['source_family'] not in seen:selected.append(m);seen.add(m['source_family'])
        selected=selected[:self.config['max_docs']]
        passages=[];omissions=list(quality_deferred);remaining=self.config['max_input_chars']
        for m in docs:
            if m not in selected:
                omissions.append({'material_id':m['material_id'],'reason':'document/family budget; retained for later exploration'});continue
            from .passage_selection import select_passages,reference_notes,note_chars
            budget=min(self.config['max_chars_per_doc'],remaining)
            ranges,omitted=select_passages(m['cleaning'],budget)
            for start,end in ranges:
                text=m['text'][start:end]
                chosen=[b for b in m['cleaning']['blocks'] if 'clean_start' in b and start<=b['clean_start'] and b['clean_end']<=end]
                notes=reference_notes(m['cleaning'],chosen);remaining-=len(text)+note_chars(notes)
                passages.append({'source_id':'S'+digest({'material':m['material_id'],'start':start,'end':end})[:12],
                  'material_id':m['material_id'],'text':text,'start':start,'end':end,'original_chars':len(m['text']),
                  'source_family':m['source_family'],'provenance':m['provenance'],'document_sha256':digest(m['text'].encode()),
                  'quote_basis':'cleaned_text','selection':'whole_blocks_across_sections','reference_notes':notes,'sections':list(dict.fromkeys(h for b in chosen for h in b.get('section',[]))),
                  'cleaning_version':m['cleaning']['version'],'raw_source_sha256':m['cleaning']['source_sha256'],
                  'source_locator':m['cleaning']['source_locator'],
                  'source_blocks':[dict(b) for b in m['cleaning']['blocks']
                      if 'clean_start' in b and start<=b['clean_start'] and b['clean_end']<=end]})
            omissions.extend({'material_id':m['material_id'],'reason':'complete blocks outside character budget','start':a,'end':b}
                             for a,b in omitted)
            omissions.extend({'material_id':m['material_id'],'reason':b['reason'],'block_id':b['block_id'],
                              'raw_start':b['raw_start'],'raw_end':b['raw_end'],'next_action':'parse_source_markup'}
                             for b in m['cleaning']['blocks'] if b.get('decision')=='defer')
        ready=[];image_gaps=[]
        for m in images[:self.config['max_images']]:
            status=m.get('bytes',{})
            if status.get('status')=='verified_bytes':
                p=Path(status['path'])
                if not p.is_file() or digest(p.read_bytes())!=m['record'].get('sha256'):status={'status':'changed_or_missing_bytes'}
            else:status=await fetch_image(m['record'],self.run,self.config)
            item={**m,'image_id':'I'+m['record'].get('sha256','')[:12],'bytes':status}
            if status.get('status')=='verified_bytes':ready.append(item)
            else:image_gaps.append(item)
        out={**row,'material_pack':{'passages':passages,'images':ready,'duplicates':duplicates,'omissions':omissions,'image_gaps':image_gaps,
               'coverage':'Selected input only; no whole-concept completeness claim. Same-page variants are not independent sources.'}}
        if not passages:out['blocked']={'stage':self.label,'reason':'no_source_text_in_selected_materials','detail':'Images retained; image-only knowledge extraction not implemented in this pilot.'}
        return out

def model_passages(passages):
    # Provenance can include large source blocks; it stays on disk, outside model budgets.
    return [{**{k:p[k] for k in ('source_id','text','source_family','start','end')},
             'reference_notes':p.get('reference_notes',[]),'sections':p.get('sections',[])} for p in passages]


class ExtractKnowledge(Stage):
    label='extract'
    async def process(self,row):
        passages=row['material_pack']['passages']
        result,call=await self.model.json(self.label,message(EXTRACT,{'concept':row['identity']['target_label'],'passages':model_passages(passages)}))
        check.knowledge(result,passages)
        return {**row,'extraction':result,'extraction_call':call}

class ConsolidateKnowledge(Stage):
    label='consolidate'
    async def process(self,row):
        passages=row['material_pack']['passages']
        result,call=await self.model.json(self.label,message(CONSOLIDATE,{'concept':row['identity']['target_label'],'passages':model_passages(passages),'candidates':row['extraction'],'previous_unresolved_conflicts':row['extraction'].get('unresolved_conflicts',[])}))
        check.knowledge(result,passages)
        if not isinstance(result.get('changes'),list):raise ValueError('Consolidation must preserve change reasons')
        result=quarantine_conflicts(result,row['extraction'])
        return {**row,'knowledge':result,'consolidation_call':call,'knowledge_review_status':'machine_candidate; semantic correctness and conflict resolution await review'}

class CheckImageSupport(Stage):
    label='evidence'
    async def process(self,row):
        images=row['material_pack']['images'];facts=row['knowledge']['facts']
        if not images or not facts:
            return {**row,'image_evidence':{'status':'not_run','reason':'no_available_images' if not images else 'no_knowledge_candidates','images':[],'support':[]}}
        from PIL import Image,ImageOps
        content=[{'type':'text','text':EVIDENCE+'\n知识：'+json.dumps(facts,ensure_ascii=False)}]
        roles=[]
        for im in images:
            path=Path(im['bytes']['path']);raw=path.read_bytes()
            if digest(raw)!=im['record']['sha256']:raise ValueError('Image changed before model input')
            with Image.open(io.BytesIO(raw)) as source:
