"""V4 material stages: reusable business operators, no model calls."""
import asyncio
import hashlib
from pathlib import Path
from .contracts import digest, immutable, read
from .sources import inspect_source, scan_source

class InspectSource:
    label='inspect_sources';concurrency=2;queue_depth=2;catch=()
    async def __call__(self,row):return await asyncio.to_thread(inspect_source,row)

class CollectRows:
    label='collect_results';concurrency=1;queue_depth=2;catch=()
    def __init__(self):self.results=[]
    async def __call__(self,row):self.results.append(row);return row

class ScanSource:
    label='scan_materials';concurrency=2;queue_depth=2;catch=()
    def __init__(self,run,requests,links,max_rows,code_hash):
        self.run=Path(run);self.requests=requests;self.links=links;self.max_rows=max_rows;self.code_hash=code_hash
        self.reused=0;self.executed=0
    async def __call__(self,source):
        key=digest({'source':source,'requests':self.requests,'links':self.links,'max_rows':self.max_rows,'code':self.code_hash})
        p=self.run/'source_tasks'/f'{key}.json'
        if p.exists():self.reused+=1;return read(p)
        result=await asyncio.to_thread(scan_source,source,self.requests,self.links,self.max_rows)
        immutable(p,result);self.executed+=1;return result


def safe_local(base,relative):
    base=Path(base).resolve();p=(base/relative).resolve()
    if not p.is_relative_to(base):raise ValueError('material path escapes source root')
    return p


def verify_image(record,dataset,blob_roots):
    from PIL import Image
    relative=record.get('path')
    if not relative:return {'status':'missing_locator'}
    for base in [dataset,*blob_roots]:
        try:p=safe_local(base,relative)
        except ValueError:return {'status':'invalid_path'}
        if not p.is_file():continue
        try:
            h=hashlib.sha256()
            with p.open('rb') as f:
                for chunk in iter(lambda:f.read(1024*1024),b''):h.update(chunk)
            actual=h.hexdigest()
            if not record.get('sha256'):return {'status':'missing_expected_hash','path':str(p),'actual_sha256':actual}
            if actual!=record['sha256']:return {'status':'hash_mismatch','path':str(p),'actual_sha256':actual}
            with Image.open(p) as im:im.load();size=list(im.size);fmt=im.format
            return {'status':'verified_bytes','path':str(p),'sha256':actual,'dimensions':size,'format':fmt,
                    'knowledge_support':'not_reviewed','generation_origin':'not_verified'}
        except (OSError,ValueError,Image.DecompressionBombError) as e:return {'status':'decode_error','path':str(p),'error':str(e)}
    return {'status':'not_local','remote_locator':record.get('content_url'),
            'note':'A URL may be a Commons page, not image bytes. COS fetching is not yet connected; absence here is not absence of material.'}

class AssembleMaterial:
    label='assemble_material_bundle';concurrency=1;queue_depth=2;catch=()
    def __init__(self,scans,dataset,blob_roots,max_images):
        self.scans=scans;self.dataset=Path(dataset);self.blob_roots=blob_roots;self.max_images=max_images
    async def __call__(self,task):return await asyncio.to_thread(self.build,task)
    def build(self,task):
        request=task['request'];associations=[];coverage=[];verified=0
        for scan in self.scans:
            kind=scan['source']['kind']
            if kind in ('legacy_concepts','legacy_docs','legacy_images') and request['kind']!='legacy':continue
            if kind not in ('legacy_concepts','legacy_docs','legacy_images') and request['kind']!='qid':continue
            coverage.append({'source_path':scan['source']['path'],'kind':kind,'status':scan['status'],'scan':scan['scan']})
            for m in scan['matches']:
                if m['request']!=request:continue
                a={'kind':kind,**{k:v for k,v in m.items() if k!='request'},'knowledge_support':'not_reviewed'}
                if kind=='legacy_docs':
                    relative=m['record'].get('path')
                    try:
                        if not relative:raise ValueError('missing page path')
                        p=safe_local(self.dataset,relative)
                        raw=p.read_bytes()
                        a['document']={'path':str(p),'sha256':digest(raw),'text':raw.decode('utf-8'),'status':'readable'}
                    except (ValueError,OSError) as e:a['document']={'status':'read_error','error':str(e)}
                if kind in ('legacy_images','qid_images'):
                    if verified<self.max_images:
                        a['bytes']=verify_image(m['record'],self.dataset,self.blob_roots);verified+=1
                    else:a['bytes']={'status':'budget_limited','note':'Image verification limit reached; remaining candidates retained.'}
                    a['caption']={'existing':m['record'].get('caption'),'provenance':'source_record; origin not yet classified','supplemental':None}
                associations.append(a)
        return {**task,'schema':'curation-v4-material-bundle/1','stage':'materials_prepared',
                'knowledge_status':'not_extracted','identity_status':'source_identity_only; cross-source merge not adjudicated',
                'materials':associations,'coverage':coverage,
                'gaps':['Cross-source identity matching/merge remains a separate reviewed step.',
                        'No source or image is approved as knowledge evidence by this preparation flow.']}

class SaveBundle:
    label='save_material_bundle';concurrency=1;queue_depth=2;catch=()
    def __init__(self,run):self.run=Path(run);self.results=[]
    async def __call__(self,row):
        p=self.run/'bundles'/f'{row["task_id"]}.json'
        immutable(p,row)
        self.results.append({'task_id':row['task_id'],'concept_id':row['concept_id'],'request':row['request'],'path':str(p),'materials':len(row['materials'])})
        return row

code.passage_selection.py:
"""Select complete source blocks across sections, with exact omitted ranges."""
from collections import OrderedDict


def reference_notes(cleaning, blocks):
    definitions={r['reference_id']:r for b in cleaning['blocks'] for r in b.get('references',[])
                 if r.get('reference_id') and (r.get('content') or r.get('parameters'))}
    result={}
    for b in blocks:
        for r in b.get('references',[]):
            key=r.get('reference_id')
            if key:result[key]=definitions.get(key,r)
    return list(result.values())


def note_chars(notes):
    return sum(len(r.get('raw_text','')) for r in notes)


def select_passages(cleaning, budget):
    text=cleaning['text'];sections=OrderedDict()
    blocks=[b for b in cleaning['blocks'] if b.get('decision')=='keep' and 'clean_start' in b
            and b.get('kind')!='heading' and not b['text'].startswith('[Source ')]
    for b in blocks:
        sections.setdefault(tuple(b.get('section',[])),[]).append(b)
    # Round robin gives every represented section an opportunity. Whole blocks
    # preserve sentences, tables, and necessary conditions; oversized blocks wait.
    selected=[];remaining=budget
    queues=list(sections.values())
    while any(queues):
        for queue in queues:
            if not queue:continue
            b=queue.pop(0);cost=b['clean_end']-b['clean_start']+note_chars(reference_notes(cleaning,[b]))+2
            if cost<=remaining:selected.append(b);remaining-=cost
    selected.sort(key=lambda b:b['clean_start'])
    ranges=[]
    for b in selected:
        if ranges and b['clean_start']-ranges[-1][1]<=2:
            ranges[-1]=(ranges[-1][0],b['clean_end'])
        else:ranges.append((b['clean_start'],b['clean_end']))
    # Separators in merged runs count against the same input budget.
    while sum(e-a for a,e in ranges)>budget and ranges:
        selected.pop();ranges=[]
        for b in selected:
            if ranges and b['clean_start']-ranges[-1][1]<=2:ranges[-1]=(ranges[-1][0],b['clean_end'])
            else:ranges.append((b['clean_start'],b['clean_end']))
    omitted=[];cursor=0
    for a,e in ranges:
        if text[cursor:a].strip():omitted.append((cursor,a))
        cursor=e
    if text[cursor:].strip():omitted.append((cursor,len(text)))
    return ranges,omitted

code.pipeline.py:
"""Legacy prepared-query-bundle runner; retains historical status/inspect.

Current record-first entry: python -m curation.v4.record_flow.
Knowledge operators remain shared with that entry.

run --input-run PREPARED_RUN --run NEW_RUN [--config JSON] [--through STAGE]
status --run RUN; inspect --run RUN --stage STAGE [--case legacy:芦笙]
No notebook generation, permanent identity merge, benchmark generation or scoring.
"""
import argparse
import json
from pathlib import Path
from .contracts import ROOT,code_fingerprint,source_code,runtime_version,digest,read,immutable,run_lock
from .flow import execute,check_run_location
from .operators import CollectRows
from .local_model import LocalModel
from .knowledge_stages import CleanMaterials,ResolveIdentity,OrganizeMaterials,ExtractKnowledge,ConsolidateKnowledge,CheckImageSupport,ExportCandidates

STAGES=[CleanMaterials,ResolveIdentity,OrganizeMaterials,ExtractKnowledge,ConsolidateKnowledge,CheckImageSupport,ExportCandidates]
DEFAULT={'base_url':'http://127.0.0.1:8000/v1','model':'qwen3.8-27b','max_calls':16,'max_output_tokens':3500,
         'timeout_s':240,'max_cases':4,'identity_docs':12,'identity_images':12,'max_docs':2,'max_chars_per_doc':6500,'max_input_chars':13000,
         'max_images':2,'max_image_bytes':8*1024*1024,'cos_base_url':None}


def run(input_run,run_dir,config,through='export',model_factory=LocalModel):
    input_run=Path(input_run).resolve();run_dir=Path(run_dir).resolve()
    prepared=read(input_run/'manifest.json');report=read(input_run/'report.json')
    check_run_location(run_dir,prepared['project'],prepared['dataset'])
    if input_run==run_dir:raise ValueError('Knowledge stages need a new run, not the historical material directory')
    unknown=set(config)-set(DEFAULT)
    if unknown:raise ValueError(f'Unknown config keys: {unknown}')
    config={**DEFAULT,**config}
    for key in ['max_calls','max_output_tokens','max_cases','identity_docs','identity_images','max_docs','max_chars_per_doc','max_input_chars','max_images','max_image_bytes']:
        if not isinstance(config[key],int) or config[key]<0:raise ValueError(f'Invalid limit: {key}')
    if not 0<len(report['bundles'])<=config['max_cases']:raise ValueError('Input batch exceeds the configured small-batch limit')
    if through not in [s.label for s in STAGES]:raise ValueError('Unknown stage')
    inputs=[];hashes={}
    for item in report['bundles']:
        p=Path(item['path']).resolve()
        if not p.is_relative_to(input_run/'bundles'):raise ValueError('Bundle reference escapes input run')
        raw=p.read_bytes();bundle=json.loads(raw);hashes[str(p)]=digest(raw)
        if any(m['kind']=='clean_docs' for m in bundle['materials']):
            raise ValueError('Historical clean_docs inputs are retired; prepare a new run from datasets. Use inspect for old results.')
        inputs.append({'case_id':digest({'concept_id':bundle['concept_id'],'bundle_hash':digest(raw)})[:20],'bundle':bundle})
    with run_lock(run_dir):
        manifest={'phase':'small_batch_knowledge_candidates','input_run':str(input_run),'input_manifest_sha256':digest((input_run/'manifest.json').read_bytes()),
                  'input_report_sha256':digest((input_run/'report.json').read_bytes()),'bundle_hashes':hashes,
                  'config':config,'code_hash':code_fingerprint(),'runtime':runtime_version(),
                  'stages':[s.label for s in STAGES],'scope':'Engineering/development candidates, not formal sampling or human gold.'}
        immutable(run_dir/'pipeline_manifest.json',manifest);immutable(run_dir/'code_snapshot.json',source_code())
        model=model_factory(run_dir,config);ops=[]
        for cls in STAGES:
            ops.append(cls(run_dir,config,model))
            if cls.label==through:break
        collector=CollectRows();execute(inputs,*ops,collector)
        return {'through':through,'cases':len(inputs),'calls_executed_this_invocation':model.calls,
                'stage_tasks_executed':{s.label:s.executed for s in ops},'stage_tasks_reused':{s.label:s.reused for s in ops},
                'results':[{'case_id':r['case_id'],'request':r['bundle']['request'],'blocked':r.get('blocked'),
                            'facts':len(r.get('knowledge',{}).get('facts',[])),'image_support_rows':len(r.get('image_evidence',{}).get('result',{}).get('support',[]))} for r in collector.results]}


def status(run_dir):
    run_dir=Path(run_dir);manifest=read(run_dir/'pipeline_manifest.json');stages={}
    for stage in manifest['stages']:
        rows=[read(p)['output'] for p in sorted((run_dir/'stages'/stage).glob('*.json'))]
        stages[stage]={'saved':len(rows),'blocked':sum(bool(r.get('blocked')) for r in rows)}
    usage={};successful=0;failed=0
    for p in (run_dir/'calls').glob('*.response.json'):
        r=read(p)
        if r['status_code']==200:
            successful+=1
            for k,v in r['body'].get('usage',{}).items():
                if isinstance(v,(int,float)):usage[k]=usage.get(k,0)+v
        else:failed+=1
    return {'stages':stages,'call_requests':len(list((run_dir/'calls').glob('*.request.json'))),
            'http_successes':successful,'http_failures':failed,'usage':usage,'model':manifest['config']['model'],
            'note':'HTTP success and schema/quote checks are not semantic approval.'}


def inspect(run_dir,stage,case=None):
    outputs=[]
    for p in sorted((Path(run_dir)/'stages'/stage).glob('*.json')):
        row=read(p)['output'];r=row['bundle']['request'];label=r['kind']+':'+r['value']
        if case and case not in (label,row['case_id']):continue
        out={'case':label,'stage':stage,'blocked':row.get('blocked'),'record_path':str(p.resolve())}
        if stage=='clean':out['result']=row.get('cleaning_summary')
        elif stage=='identity':out['result']=row.get('identity');out['unexamined_materials']=len(row.get('identity_unexamined',[]))
        elif stage=='organize':
            pack=row.get('material_pack',{});out['passages']=[{k:p[k] for k in ('source_id','source_family','start','end','original_chars')} for p in pack.get('passages',[])]
            out['images']=[{'image_id':i['image_id'],'bytes':i['bytes']} for i in pack.get('images',[])]
            out['duplicates']=pack.get('duplicates',[]);out['omissions']=pack.get('omissions',[])
            out['image_gaps']=[{'material_id':i['material_id'],'bytes':i['bytes']} for i in pack.get('image_gaps',[])]
        elif stage=='extract':out['result']=row.get('extraction')
        elif stage=='consolidate':out['result']=row.get('knowledge')
        elif stage=='evidence':out['result']=row.get('image_evidence')
        else:out['result']=row.get('export')
        outputs.append(out)
    return outputs


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('action',choices=['run','status','inspect'])
    p.add_argument('--run',required=True,type=Path);p.add_argument('--input-run',type=Path);p.add_argument('--config',type=Path)
    p.add_argument('--through',choices=[s.label for s in STAGES],default='export')
    p.add_argument('--stage',choices=[s.label for s in STAGES],default='identity');p.add_argument('--case')
    a=p.parse_args()
    if a.action=='run':
        if not a.input_run:p.error('run needs --input-run')
        result=run(a.input_run,a.run,read(a.config) if a.config else {},a.through)
    elif a.action=='status':result=status(a.run)
    else:result=inspect(a.run,a.stage,a.case)
    print(json.dumps(result,ensure_ascii=False,indent=2))

if __name__=='__main__':main()

code.quality_policy.py:
"""Business dispositions: retained material is not automatically extraction input."""
import re


def material_disposition(cleaning):
    warnings=set(cleaning.get('warnings',[]))
    reasons=[];actions=[]
    if cleaning.get('status')=='unavailable' or not cleaning.get('text','').strip():
        reasons.append('no_usable_body');actions.append('reacquire_source')
    routes={'possible_truncated_snippet':'fetch_full_document',
            'access_restriction_or_challenge_marker':'check_access_or_reacquire',
            'residual_navigation_requires_review':'separate_article_body',
            'unexpanded_wiki_template_retained':'parse_source_markup',
            'mixed_html_markup_retained':'parse_source_markup',
            'malformed_html_tail_retained':'repair_or_reacquire',
            'auxiliary_html_retained':'separate_article_body',
            'mixed_script_language_review':'review_language_and_readability',
            'partial_body_context_requires_review':'parse_source_markup'}
    for warning,action in routes.items():
        if warning in warnings:reasons.append(warning);actions.append(action)
    # Unknown cleaning warnings are not silently certified by a new ruleset.
    remaining=warnings-set(routes)-{'access_error_page_no_body','no_body_blocks','partial_markup_deferred'}
    if remaining:reasons.extend(sorted(remaining));actions.append('review_cleaning')
    if cleaning.get('status')=='needs_review' and not reasons:
        reasons.append('cleaning_needs_review');actions.append('review_cleaning')
    return {'status':'pending' if reasons else 'eligible_for_identity',
            'reasons':reasons,'next_actions':sorted(set(actions)),
            'scope':'Processing eligibility only; identity and factual reliability are not certified.'}


def quarantine_conflicts(result, previous=None):
    """Never silently forget extraction conflicts; isolate affected statements.

    Explicit fact IDs allow unrelated statements in the same source to continue.
    Missing correspondence conservatively holds statements sharing those sources,
    and records that this is uncertainty about scope, not a proven contradiction.
    This operator cannot adjudicate semantic resolutions automatically.
    """
    from .contracts import digest
    conflicts=[];seen=set()
    for conflict in result.get('unresolved_conflicts',[])+(previous or {}).get('unresolved_conflicts',[]):
        key=digest({'source_ids':sorted(conflict['source_ids']),'issue':conflict['issue']})
        if key not in seen:conflicts.append({**conflict,'conflict_id':key});seen.add(key)
    ready=[];deferred=[]
    facts=result['facts'];ids={f['fact_id'] for f in facts}
    for fact in facts:
        reasons=[]
        for conflict in conflicts:
            affected=conflict.get('affected_fact_ids')
            explicit=isinstance(affected,list) and bool(affected) and set(affected)<=ids
            if explicit:
                touches=fact['fact_id'] in affected;basis='explicit_fact_correspondence'
            else:
                touches=bool({e['source_id'] for e in fact['evidence']}&set(conflict['source_ids']))
                basis='unresolved_correspondence_shared_source'
            if touches:reasons.append({'conflict_id':conflict['conflict_id'],'basis':basis})
        if reasons:deferred.append({'fact':fact,'reasons':reasons,'next_action':'resolve_conflict_with_source_evidence'})
        else:ready.append(fact)
    return {**result,'facts':ready,'deferred_facts':deferred,'unresolved_conflicts':conflicts}


def image_followups(facts,evidence):
    rows=evidence.get('result',{}).get('support',[])
    return [{'fact_id':f['fact_id'],'next_action':'find_or_verify_image_support',
             'reason':'no_full_image_support_in_checked_inputs',
             'scope':'Does not reject text knowledge or claim that supporting images do not exist.'}
            for f in facts if not any(r['fact_id']==f['fact_id'] and r['status']=='full' for r in rows)]


def identity_followups(result):
    actions={'different_identity':'reassociate_material','uncertain':'resolve_identity','unreadable':'review_language_or_reacquire'}
    rejected={r['material_id'] for r in result.get('rejected_materials',[])}
    return [{'material_id':r['material_id'],'reason':r['reason'],
             'next_actions':[actions.get(r['relation'],'review_identity_rejection')]}
            for r in result.get('material_reviews',[]) if r['material_id'] in rejected]


def defer_invalid_identity_quotes(result, previews):
    """Keep invalid model evidence visible and isolate that material, not its peers."""
    import copy
    out=copy.deepcopy(result);by_id={p['material_id']:p for p in previews};issues=[]
    for r in out.get('material_reviews',[]):
        p=by_id.get(r.get('material_id'))
        if p is None:continue  # global schema/coverage check still rejects this
        texts=[p.get('title') or '',p.get('caption') or '',p.get('text_preview') or '']+[s['text'] for s in p.get('text_spans',[])]
        q=r.get('quote');accepted=r['material_id'] in out.get('accepted_material_ids',[])
        invalid=not isinstance(q,str) or (accepted and not q.strip()) or (isinstance(q,str) and not any(q in t for t in texts))
        if not invalid:continue
        issues.append({'material_id':r['material_id'],'reason':'identity_quote_not_verbatim_in_supplied_input','original_review':copy.deepcopy(r)})
        out['accepted_material_ids']=[i for i in out['accepted_material_ids'] if i!=r['material_id']]
        out['rejected_materials']=[x for x in out['rejected_materials'] if x['material_id']!=r['material_id']]+[{'material_id':r['material_id'],'reason':'invalid quoted basis; pending identity evidence'}]
        r.update(relation='uncertain',quote='',reason='Original model quote invalid; decision withheld, not a confirmed mismatch.')
    if issues and out.get('status')=='resolved' and not out['accepted_material_ids']:
        out.update(status='insufficient',reason='No accepted material retains valid quoted identity evidence.')
    out['protocol_issues']=issues
    return out

